const PhoneNumberMaskParser phoneNumberMaskParser = PhoneNumberMaskParser(
    targetMask: "+## #### ######",
    defaultMask: "+### (###) ### ####",
    isPlus: false,
    isEndless: true,
);

final PhoneNumberMaskParserResult result = phoneNumberMaskParser.apply(
  phoneNumber: "4492330323912034",
);
